<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{AuditLog,Branch,BranchStockTransfer,MedicineBatch,StockMovement}; use App\Services\BranchContext;
use App\Services\JournalPostingService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class BranchTransferController extends Controller
{
 public function index(){return BranchStockTransfer::with(['fromBranch:id,name','toBranch:id,name','items.medicine:id,name,strength'])->latest()->paginate(20);}
 public function store(Request $r){$d=$r->validate(['from_branch_id'=>'required|exists:branches,id','to_branch_id'=>'required|different:from_branch_id|exists:branches,id','notes'=>'nullable|string|max:1000','items'=>'required|array|min:1','items.*.source_batch_id'=>'required|exists:medicine_batches,id','items.*.quantity'=>'required|integer|min:1']);$t=DB::transaction(function()use($d){$t=BranchStockTransfer::create(['transfer_no'=>'TRF-'.now()->format('Ymd').'-'.strtoupper(str()->random(5)),'from_branch_id'=>$d['from_branch_id'],'to_branch_id'=>$d['to_branch_id'],'status'=>'pending','notes'=>$d['notes']??null,'requested_by'=>auth()->id()]);foreach($d['items'] as $i){$b=MedicineBatch::with('medicine')->findOrFail($i['source_batch_id']);abort_unless((int)$b->branch_id===(int)$d['from_branch_id'],422,'A selected batch does not belong to the source branch.');abort_if($b->is_quarantined,422,'Quarantined batches cannot be transferred.');abort_if($b->quantity<$i['quantity'],422,'Transfer quantity exceeds batch stock.');abort_if($b->expiry_date && $b->expiry_date->lt(today()),422,'Expired batches cannot be transferred as sellable stock.');$t->items()->create(['medicine_id'=>$b->medicine_id,'source_batch_id'=>$b->id,'quantity'=>$i['quantity']]);}return $t;});return response()->json(['message'=>'Transfer request created.','data'=>$t->load('items.medicine')],201);}
 public function approve(BranchStockTransfer $transfer,Request $r){$d=$r->validate(['decision'=>'required|in:approve,reject']);abort_unless($transfer->status==='pending',422,'Only pending transfers can be reviewed.');if($d['decision']==='reject'){$transfer->update(['status'=>'rejected','approved_by'=>auth()->id(),'approved_at'=>now()]);return response()->json(['message'=>'Transfer rejected.']);}
 DB::transaction(function()use($transfer){$transfer=BranchStockTransfer::lockForUpdate()->findOrFail($transfer->id);abort_unless($transfer->status==='pending',422,'Transfer was already reviewed.');$transfer->load('items');foreach($transfer->items as $item){$source=MedicineBatch::lockForUpdate()->findOrFail($item->source_batch_id);abort_if($source->branch_id!=$transfer->from_branch_id || $source->quantity<$item->quantity,422,'Source batch stock changed; review the transfer again.');$source->decrement('quantity',$item->quantity);$remaining=(int)$item->quantity;foreach(DB::table('batch_location_stocks')->where('medicine_batch_id',$source->id)->where('quantity','>',0)->orderBy('id')->lockForUpdate()->get() as $bin){if($remaining<=0)break;$take=min((int)$bin->quantity,$remaining);DB::table('batch_location_stocks')->where('id',$bin->id)->decrement('quantity',$take);$remaining-=$take;}if($source->medicine->requires_controlled_tracking){DB::table('controlled_medicine_register')->insert(['branch_id'=>$transfer->from_branch_id,'medicine_id'=>$source->medicine_id,'batch_id'=>$source->id,'transaction_type'=>'transfer_out','quantity_change'=>-((int)$item->quantity),'balance_after'=>$source->fresh()->quantity,'reference_no'=>$transfer->transfer_no,'reason'=>'Inter-branch stock transfer out','recorded_by'=>auth()->id(),'recorded_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}StockMovement::create(['medicine_id'=>$source->medicine_id,'medicine_batch_id'=>$source->id,'branch_id'=>$transfer->from_branch_id,'type'=>'branch_transfer_out','quantity'=>-$item->quantity,'balance_after'=>$source->medicine->fresh()->total_stock,'reference'=>$transfer->transfer_no,'note'=>'Transfer to branch '.$transfer->to_branch_id,'user_id'=>auth()->id()]);$dest=MedicineBatch::create(['medicine_id'=>$source->medicine_id,'purchase_id'=>null,'supplier_id'=>$source->supplier_id,'branch_id'=>$transfer->to_branch_id,'batch_no'=>$source->batch_no,'expiry_date'=>$source->expiry_date,'purchase_price'=>$source->purchase_price,'sale_price'=>$source->sale_price,'initial_quantity'=>$item->quantity,'quantity'=>$item->quantity]);$item->update(['destination_batch_id'=>$dest->id]);if($source->medicine->requires_controlled_tracking){DB::table('controlled_medicine_register')->insert(['branch_id'=>$transfer->to_branch_id,'medicine_id'=>$source->medicine_id,'batch_id'=>$dest->id,'transaction_type'=>'transfer_in','quantity_change'=>(int)$item->quantity,'balance_after'=>$dest->quantity,'reference_no'=>$transfer->transfer_no,'reason'=>'Inter-branch stock transfer in','recorded_by'=>auth()->id(),'recorded_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}StockMovement::create(['medicine_id'=>$dest->medicine_id,'medicine_batch_id'=>$dest->id,'branch_id'=>$transfer->to_branch_id,'type'=>'branch_transfer_in','quantity'=>$item->quantity,'balance_after'=>$dest->medicine->total_stock,'reference'=>$transfer->transfer_no,'note'=>'Transfer from branch '.$transfer->from_branch_id,'user_id'=>auth()->id()]);}$transfer->update(['status'=>'completed','approved_by'=>auth()->id(),'approved_at'=>now(),'completed_by'=>auth()->id(),'completed_at'=>now()]);app(JournalPostingService::class)->postBranchTransfer($transfer->load('items'));AuditLog::create(['user_id'=>auth()->id(),'action'=>'branch_stock_transfer_completed','subject_type'=>BranchStockTransfer::class,'subject_id'=>$transfer->id,'new_values'=>['transfer_no'=>$transfer->transfer_no,'from_branch_id'=>$transfer->from_branch_id,'to_branch_id'=>$transfer->to_branch_id],'ip_address'=>request()->ip()]);});\App\Services\StockService::flushCache([(int)$transfer->from_branch_id,(int)$transfer->to_branch_id]);return response()->json(['message'=>'Stock transfer completed.','data'=>$transfer->fresh('items')]);}
 public function stock(Request $r){$branch=(int)$r->query('branch_id',BranchContext::id());abort_unless(Branch::whereKey($branch)->exists(),404);return MedicineBatch::with('medicine:id,name,strength,unit')->where('branch_id',$branch)->where('quantity','>',0)->where('is_quarantined',false)->orderBy('expiry_date')->paginate(30);}
}
